'use client';
import { useId, useRef, useState, type KeyboardEvent } from 'react';
import { spring, springToLinear, useStudioMotion } from '../../../motion';
import { ClubMark, MeteorSky } from './art';
import { TokenViewer } from './TokenViewer';
import styles from './styles.module.css';

const POP = springToLinear(spring.pop);
const ICS = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Saltmarsh Sky Club//Sample event//EN', 'BEGIN:VEVENT',
  'UID:session-12-2026@saltmarsh-sky.invalid', 'DTSTAMP:20261123T100000Z', 'DTSTART:20261212T193000Z', 'DTEND:20261212T220000Z',
  'SUMMARY:Saltmarsh Sky Club — Session 12 (sample event)', 'LOCATION:Holm Marsh sea wall car park',
  'DESCRIPTION:Weather permitting. Go or no-go is posted in the club feed by 16:00 on the day.', 'END:VEVENT', 'END:VCALENDAR',
].join('\r\n');

type Icon = 'star' | 'spark' | 'hand' | 'eye';
const ICONS: Record<Icon, string> = {
  star: 'M12 3.500l2.500 5.300 5.800.7-4.300 4 1.100 5.700L12 16.400l-5.100 2.800L8 13.500 3.700 9.500l5.800-.7z',
  spark: 'M12 3c.6 4.600 2.400 6.400 7 7-4.600.6-6.400 2.400-7 7-.6-4.600-2.400-6.400-7-7 4.600-.6 6.400-2.400 7-7z',
  hand: 'M8 12V6.500a1.500 1.500 0 0 1 3 0V11m0-1V5a1.500 1.500 0 0 1 3 0v6m0-4.500a1.500 1.500 0 0 1 3 0V14a6 6 0 0 1-6 6h-.5a6 6 0 0 1-4.800-2.400L4 14.500a1.500 1.500 0 0 1 2.400-1.800L8 14.500',
  eye: 'M2.500 12S6 5.500 12 5.500 21.500 12 21.500 12 18 18.500 12 18.500 2.500 12 2.500 12z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6z',
};

function Reactions({ items }: { items: readonly { id: string; label: string; icon: Icon; base: number }[] }) {
  const { reduced } = useStudioMotion();
  const [on, setOn] = useState<Record<string, boolean>>({});
  const anims = useRef(new Set<Animation>());
  const press = (id: string, btn: HTMLButtonElement) => {
    const next = !on[id];
    setOn((s) => ({ ...s, [id]: next }));
    const icon = btn.querySelector('svg');
    if (reduced || !next || !icon || typeof icon.animate !== 'function') return;
    const a = icon.animate([{ transform: 'scale(0.55) rotate(-12deg)' }, { transform: 'none' }], { duration: POP.duration, easing: POP.easing });
    anims.current.add(a);
    const done = () => anims.current.delete(a);
    a.finished.then(done, done);
  };
  return (
    <div className={styles.reactions} role="group" aria-label="Reactions (sample counts)">
      {items.map((r) => (
        <button key={r.id} type="button" className={styles.reaction} aria-pressed={!!on[r.id]} onClick={(e) => press(r.id, e.currentTarget)}>
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d={ICONS[r.icon]} /></svg>
          {r.label} <span className={styles.reactionCount}>{r.base + (on[r.id] ? 1 : 0)}</span>
        </button>
      ))}
    </div>
  );
}

function Byline({ id, when, iso, tag }: { id: string; when: string; iso: string; tag?: string }) {
  return (
    <div className={styles.postHead}>
      <ClubMark className={styles.avatar} />
      <p id={id} className={styles.byline}>
        <span className={styles.author}>Saltmarsh Sky Club</span>
        <span className={styles.meta}>@saltmarshsky · <time dateTime={iso} title={new Date(iso).toUTCString()}>{when}<span className="mk-sr-only"> ago</span></time></span>
      </p>
      {tag ? <span className={styles.tag}>{tag}</span> : null}
    </div>
  );
}

export default function SocialPost3D() {
  const uid = useId();
  const [rsvp, setRsvp] = useState<'going' | 'maybe' | 'no' | ''>('');
  const ids = { token: `${uid}-token`, event: `${uid}-event`, log: `${uid}-log` };

  const onFeedKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key !== 'PageDown' && e.key !== 'PageUp') return;
    const list = Array.from(e.currentTarget.querySelectorAll<HTMLElement>(':scope > article'));
    const at = list.findIndex((a) => a.contains(document.activeElement));
    const next = list[Math.max(0, Math.min(list.length - 1, at + (e.key === 'PageDown' ? 1 : -1)))];
    if (next) { e.preventDefault(); next.focus(); }
  };

  return (
    <div className={styles.root}>
      <div className={styles.page}>
        <header className={styles.club}>
          <ClubMark className={styles.clubMark} />
          <div>
            <p className={styles.sample}><span className="mk-label">Sample content</span> A fictional club; posts, people and counts are invented.</p>
            <h2 className={styles.clubName}>Saltmarsh Sky Club</h2>
            <p className={styles.clubLine}>Amateur astronomers on the Holm Marsh sea wall, once a month, red torches only.</p>
          </div>
        </header>

        <div className={styles.layout}>
          <div className={styles.feedCol}>
            <p className={styles.feedNote}><span className="mk-label">Club feed</span> Newest first. One post has a 3D model; the rest are flat.</p>
            <div role="feed" aria-busy="false" aria-label="Saltmarsh Sky Club posts" className={styles.feed} onKeyDown={onFeedKey}>
              <article className={styles.post} aria-labelledby={ids.token} aria-describedby={`${ids.token}-text`} aria-posinset={1} aria-setsize={3} tabIndex={-1}>
                <Byline id={ids.token} when="2 h" iso="2026-11-23T08:00:00Z" tag="3D post" />
                <TokenViewer />
                <div className={styles.postBody}>
                  <h3 className={styles.postTitle}>The One Orbit tokens are back from the die-maker</h3>
                  <p id={`${ids.token}-text`} className={styles.postText}>
                    One stud for every monthly session, and a ringed planet in the middle because Pell insisted. Members who log twelve sessions
                    get one at a December meeting; sessions roll over, so there is no rush and no other way to earn one.
                  </p>
                  <dl className={styles.facts}>
                    <div><dt>Diameter</dt><dd>63 mm</dd></div>
                    <div><dt>Thickness</dt><dd>13.7 mm</dd></div>
                    <div><dt>Studs</dt><dd>12, one per session</dd></div>
                    <div><dt>Finish</dt><dd>Brass (sample)</dd></div>
                  </dl>
                  <Reactions items={[{ id: 'shiny', label: 'Shiny', icon: 'spark', base: 41 }, { id: 'want', label: 'Want one', icon: 'hand', base: 27 }]} />
                </div>
              </article>

              <article className={styles.post} aria-labelledby={ids.event} aria-describedby={`${ids.event}-text`} aria-posinset={2} aria-setsize={3} tabIndex={-1}>
                <Byline id={ids.event} when="5 h" iso="2026-11-23T05:00:00Z" tag="Event" />
                <div className={styles.postBody}>
                  <div className={styles.event}>
                    <p className={styles.eventDate} aria-hidden="true"><span>Sat</span><strong>12</strong><span>Dec</span></p>
                    <div>
                      <h3 className={styles.postTitle}>Session 12, the last of the year</h3>
                      <p id={`${ids.event}-text`} className={styles.postText}>
                        Saturday 12 December 2026, 19:30–22:00 GMT, Holm Marsh sea wall car park. Weather permitting: we post go or no-go here by 16:00 on the day.
                      </p>
                    </div>
                  </div>
                  <fieldset className={styles.rsvp}>
                    <legend>Are you coming?</legend>
                    {([['going', 'Going'], ['maybe', 'Maybe'], ['no', 'Not this time']] as const).map(([v, l]) => (
                      <label key={v} className={styles.rsvpOption}>
                        <input type="radio" name={`${uid}-rsvp`} value={v} checked={rsvp === v} onChange={() => setRsvp(v)} />
                        <span>{l}</span>
                      </label>
                    ))}
                  </fieldset>
                  <p className={styles.small} aria-live="polite">
                    {rsvp ? `Saved: ${rsvp === 'going' ? 'going' : rsvp === 'maybe' ? 'maybe' : 'not this time'}. You can change it until the session starts. ` : ''}
                    Your answer is visible to club members only. Sample counts: 14 going, 6 maybe.
                  </p>
                  <a className={styles.icsLink} href={`data:text/calendar;charset=utf-8,${encodeURIComponent(ICS)}`} download="saltmarsh-session-12.ics">Add to calendar (.ics)</a>
                </div>
              </article>

              <article className={styles.post} aria-labelledby={ids.log} aria-describedby={`${ids.log}-text`} aria-posinset={3} aria-setsize={3} tabIndex={-1}>
                <Byline id={ids.log} when="9 d" iso="2026-11-14T23:30:00Z" tag="Log" />
                <div role="img" aria-label="Night sky over a sea wall: five meteor trails, a scatter of stars, and four people on the wall wearing red head-torches." className={styles.media}>
                  <MeteorSky />
                </div>
                <div className={styles.postBody}>
                  <h3 className={styles.postTitle}>Session 11: twenty-three meteors before the fog</h3>
                  <p id={`${ids.log}-text`} className={styles.postText}>
                    Clear from nine until the fog came in off the marsh at eleven. Twenty-three meteors between the four of us, two bright enough to make Pell shout.
                  </p>
                  <Reactions items={[{ id: 'clear', label: 'Clear skies', icon: 'star', base: 18 }, { id: 'saw', label: 'Saw one too', icon: 'eye', base: 9 }]} />
                </div>
              </article>
            </div>

            <section className={styles.caughtUp} aria-labelledby={`${uid}-end`}>
              <h3 id={`${uid}-end`}>You’re up to date</h3>
              <p>That’s everything the club posted this month. The next post will be the go or no-go for Session 12.</p>
            </section>
          </div>

          <aside className={styles.rail} aria-labelledby={`${uid}-how`}>
            <h3 id={`${uid}-how`} className="mk-label">How the 3D post behaves</h3>
            <ol>
              <li><strong>Poster first.</strong> The feed shows a photo; the model downloads only when you press Interact in 3D.</li>
              <li><strong>One canvas.</strong> Only one post in a feed may hold a live 3D view; the others stay flat.</li>
              <li><strong>Released.</strong> Close 3D, or scroll the post a screen away, and the scene and model are freed.</li>
              <li><strong>No gesture required.</strong> Turn, zoom, reset and spin all have buttons; the view also takes arrow keys.</li>
            </ol>
          </aside>
        </div>
      </div>
    </div>
  );
}

/**
 * Drawn media for the 2D posts (SVG, seeded so every visit renders the same sky). Decorative: the caller wraps each
 * drawing in role="img" with a written description.
 */
const NIGHT = '#0d1424';

function rng(seed: number) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

const STARS = (() => {
  const r = rng(11);
  return Array.from({ length: 90 }, () => ({ x: r() * 400, y: r() * 330, s: r() < 0.12 ? 1.6 : 0.6 + r() * 0.7, o: 0.45 + r() * 0.55 }));
})();
const METEORS = [
  { x: 92, y: 60, len: 70, a: 28 }, { x: 250, y: 42, len: 96, a: 34 }, { x: 318, y: 132, len: 54, a: 30 },
  { x: 160, y: 170, len: 44, a: 26 }, { x: 40, y: 200, len: 38, a: 32 },
];

/** Session 11: meteors over the sea wall, four red head-torches on the wall. */
export function MeteorSky() {
  return (
    <svg viewBox="0 0 400 500" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false" style={{ display: 'block', width: '100%', height: '100%' }}>
      <defs>
        <linearGradient id="sk-trail" x1="0" x2="1">
          <stop offset="0" stopColor="#f3f0e8" stopOpacity="0" />
          <stop offset="1" stopColor="#f3f0e8" stopOpacity="0.95" />
        </linearGradient>
        <linearGradient id="sk-sky" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#070b15" />
          <stop offset="0.75" stopColor={NIGHT} />
          <stop offset="1" stopColor="#1b2438" />
        </linearGradient>
      </defs>
      <rect width="400" height="500" fill="url(#sk-sky)" />
      {STARS.map((s, i) => <circle key={i} cx={s.x} cy={s.y} r={s.s} fill="#f3f0e8" opacity={s.o} />)}
      {METEORS.map((m, i) => (
        <g key={i} transform={`translate(${m.x} ${m.y}) rotate(${m.a})`}>
          <rect x={-m.len} y={-0.9} width={m.len} height={1.8} rx={0.9} fill="url(#sk-trail)" />
        </g>
      ))}
      {/* sea, wall and four observers */}
      <rect y="372" width="400" height="128" fill="#0a101c" />
      {[392, 414, 440, 470].map((y, i) => <path key={y} d={`M${20 + i * 30} ${y}h${120 - i * 12}M${230 - i * 8} ${y + 6}h${90 + i * 10}`} stroke="#3a4a6b" strokeWidth="1.2" strokeLinecap="round" />)}
      <path d="M0 352 L400 340 L400 376 L0 384Z" fill="#05080f" />
      {[86, 150, 232, 300].map((x, i) => (
        <g key={x} transform={`translate(${x} ${348 - i * 2.4})`}>
          <path d="M-5 0v-14a5 5 0 0 1 10 0v14z" fill="#05080f" />
          <circle cy="-22" r="4.5" fill="#05080f" />
          <circle cx="2.5" cy="-23" r="1.6" fill="#ff5a4a" />
        </g>
      ))}
    </svg>
  );
}

/** The club's mark: a finder-scope reticle. */
export function ClubMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 40 40" className={className} aria-hidden="true" focusable="false">
      <circle cx="20" cy="20" r="19" fill={NIGHT} />
      <circle cx="20" cy="20" r="10" fill="none" stroke="#f3f0e8" strokeWidth="1.4" />
      <path d="M20 4v8M20 28v8M4 20h8M28 20h8" stroke="#f3f0e8" strokeWidth="1.4" strokeLinecap="round" />
      <circle cx="20" cy="20" r="2" fill="#ff8f80" />
    </svg>
  );
}

/* 3D social post — "an observing log": squared log paper, mono metadata, one red-pen accent for what needs action,
   and a finder-scope frame (night sky, reticle) that holds the photo and, on request, the live model. */
.root {
  --sk-red: #b3261e;    /* ≥ 5.19:1 on bg / surface / surface-2 */
  --sk-brass: #7a4f00;
  --sk-grid: rgb(17 17 15 / 0.05);
  --sk-night: #0d1424;
  min-height: 100dvh;
  background-color: var(--mk-bg);
  background-image: linear-gradient(var(--sk-grid) 1px, transparent 1px), linear-gradient(90deg, var(--sk-grid) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --sk-red: #ff8f80; --sk-brass: #f2b632; --sk-grid: rgb(243 240 232 / 0.035); }
.page { max-width: 1100px; margin-inline: auto; padding: 0 16px 64px; }

.club { display: flex; flex-direction: column; align-items: flex-start; gap: 14px; padding: 24px 0 22px; border-bottom: 1px solid var(--mk-line-strong); }
@container (min-width: 40rem) { .club { flex-direction: row; align-items: flex-end; gap: 18px; padding-top: 32px; } }
.clubMark { flex: none; width: 56px; height: 56px; }
@container (min-width: 40rem) { .clubMark { width: 72px; height: 72px; } }
.sample { margin: 0 0 8px; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.sample > :first-child { margin-right: 8px; color: var(--sk-red); }
.clubName { margin: 0; font-family: var(--mk-font-display); font-weight: 800; font-size: clamp(2.25rem, 1.6rem + 3cqi, 3.5rem); line-height: 0.95; letter-spacing: -0.035em; }
.clubLine { margin: 8px 0 0; max-width: 52ch; font-size: 0.9375rem; line-height: 1.45; color: var(--mk-ink-muted); }

.layout { display: grid; gap: 40px; padding-top: 22px; }
@container (min-width: 60rem) {
  .layout { grid-template-columns: minmax(0, 600px) 260px; justify-content: center; gap: 56px; align-items: start; }
}
.feedCol { min-width: 0; width: 100%; max-width: 600px; margin-inline: auto; }
.feedNote { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; margin: 0 0 14px; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.feed { display: grid; gap: 28px; }
.post { background: var(--mk-surface); border: 1px solid var(--mk-line); scroll-margin-top: 64px; }
.post:focus-visible { outline: 2px solid var(--mk-focus); outline-offset: 3px; }
.postHead { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; padding: 12px 16px; }
.avatar { width: 36px; height: 36px; }
.byline { display: grid; margin: 0; line-height: 1.3; }
.author { font-size: 0.9375rem; font-weight: 600; }
.meta { font-family: var(--mk-font-mono); font-size: 0.75rem; color: var(--mk-ink-muted); }
.tag { padding: 3px 8px; border: 1px solid var(--sk-red); color: var(--sk-red); font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.media { aspect-ratio: 4 / 5; overflow: hidden; }
.postBody { padding: 14px 16px 16px; }
.postTitle { margin: 0 0 6px; font-family: var(--mk-font-display); font-size: 1.375rem; font-weight: 700; line-height: 1.15; letter-spacing: -0.015em; text-wrap: balance; }
.postText { margin: 0; max-width: 62ch; font-size: 0.9375rem; line-height: 1.55; text-wrap: pretty; }
.small { margin: 8px 0 10px; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted); }

/* ── The finder-scope frame ─────────────────────────────────────────────── */
.viewer { border-block: 1px solid var(--mk-line); padding-bottom: 12px; }
.frame {
  position: relative; aspect-ratio: 4 / 5; overflow: hidden; color: #c9c3b4;
  background: radial-gradient(circle at 50% 44%, #1d2944 0%, var(--sk-night) 64%);
}
.poster {
  position: absolute; top: 46%; left: 50%; width: min(74%, 380px); height: auto; transform: translate(-50%, -50%);
  transition: opacity var(--mk-duration-base) var(--mk-ease-standard); pointer-events: none; user-select: none;
}
.frame[data-live] .poster { opacity: 0; }
.canvas { z-index: 1; }
.reticle { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.reticle svg { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: #f3f0e8; stroke-opacity: 0.32; stroke-width: 1; vector-effect: non-scaling-stroke; }
.reticle svg * { vector-effect: non-scaling-stroke; }
.reticle span { position: absolute; font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: #c9c3b4; }
.retTL { top: 12px; left: 14px; } .retTR { top: 12px; right: 14px; }
.retBL { bottom: 12px; left: 14px; font-variant-numeric: tabular-nums; } .retBR { bottom: 12px; right: 14px; }
.frameStatus {
  position: absolute; left: 50%; bottom: 40px; z-index: 3; transform: translateX(-50%); max-width: calc(100% - 32px); box-sizing: border-box; margin: 0;
  padding: 6px 12px; border: 1px solid #5b6680; background: var(--sk-night); color: #f3f0e8; font-family: var(--mk-font-mono); font-size: 0.75rem; text-align: center;
}
.frameNote { position: absolute; left: 16px; right: 16px; bottom: 40px; z-index: 3; margin: 0; padding: 10px 12px; background: var(--sk-night); color: #f3f0e8; font-size: 0.875rem; line-height: 1.45; text-align: center; }
.textBtnInk { min-height: 24px; padding: 2px 4px; border: 0; background: none; color: #ffb3a8; font: inherit; text-decoration: underline; }

.cta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; padding: 12px 16px 0; }
.interact {
  display: inline-flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 18px;
  border: 0; border-radius: var(--mk-radius-s); background: var(--sk-red); color: var(--mk-bg); font: inherit; font-size: 0.9375rem; font-weight: 600;
}
.interact svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linejoin: round; }
.interactSize { padding: 1px 6px; border: 1px solid currentColor; font-family: var(--mk-font-mono); font-size: 0.6875rem; font-weight: 400; }
.ctaSpacer { display: inline-block; width: 1px; min-height: 48px; }
.download, .icsLink { display: inline-flex; align-items: center; min-height: 24px; color: inherit; font-size: 0.875rem; font-weight: 500; text-decoration: underline; text-underline-offset: 3px; }
.icsLink { color: var(--sk-red); font-weight: 600; }

.toolbar { display: flex; flex-wrap: wrap; gap: 6px; padding: 10px 12px 0; }
.tool {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 44px; height: 44px; padding: 0 10px; box-sizing: border-box;
  border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s); background: var(--mk-surface); color: inherit; font: inherit; font-size: 0.8125rem; font-weight: 600;
}
.tool svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.tool:hover { background: var(--mk-surface-2); }
.tool[aria-pressed='true'] { background: var(--mk-ink); color: var(--mk-bg); }
.closeIn {
  position: absolute; top: 8px; right: 8px; z-index: 3; display: inline-flex; align-items: center; gap: 6px; min-height: 40px; padding: 0 12px 0 8px;
  border: 1px solid #c9c3b4; border-radius: var(--mk-radius-s); background: var(--sk-night); color: #f3f0e8; font: inherit; font-size: 0.8125rem; font-weight: 600;
}
.closeIn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; }
.closeIn:hover { background: #1d2944; }
.viewerHint { margin: 10px 16px 0; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted); }

.facts { display: grid; gap: 0 18px; margin: 14px 0 4px; border-top: 1px solid var(--mk-line); }
@container (min-width: 30rem) { .facts { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.facts div { display: flex; justify-content: space-between; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--mk-line); font-size: 0.8125rem; }
.facts dt { color: var(--mk-ink-muted); }
.facts dd { margin: 0; font-family: var(--mk-font-mono); text-align: right; }

.reactions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.reaction {
  display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px 0 12px;
  border: 1px solid var(--mk-line-strong); border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 0.875rem; font-weight: 500;
  transition: background-color var(--mk-duration-fast) var(--mk-ease-standard), color var(--mk-duration-fast) var(--mk-ease-standard);
}
